const guideBlueprints = [
  ['complete-guide', 'Complete Guide', 'a practical start-to-finish workflow', 'Build a repeatable workflow', 'From inputs to a reviewed result'],
  ['examples', 'Examples and Scenarios', 'worked examples for realistic small-business decisions', 'Learn from realistic examples', 'Translate the result into a decision'],
  ['common-mistakes', 'Common Mistakes', 'the errors that most often make the result misleading', 'Avoid misleading inputs', 'Review the result before using it'],
  ['checklist', 'Business Checklist', 'a concise checklist for reliable records and repeatable use', 'Prepare the source information', 'Create a review checklist'],
  ['best-practices', 'Best Practices', 'practical habits for accuracy, clarity and professional output', 'Use dependable inputs', 'Build a professional routine'],
  ['fields-and-formulas', 'Fields and Formulas Explained', 'a plain-English explanation of every important input and output', 'Understand the important inputs', 'Read the output correctly'],
  ['spreadsheet-vs-online-tool', 'Spreadsheet vs. Online Tool', 'when a focused browser tool is simpler and when a spreadsheet is better', 'Compare the two workflows', 'Choose the right level of control'],
  ['recordkeeping-workflow', 'Recordkeeping Workflow', 'how to connect the calculation or document to dependable business records', 'Preserve the source records', 'Review and improve over time']
];

function guideSections(tool, blueprint, index) {
  const industryNames = tool.industries.map(item => item.name).join(', ');
  const [suffix, label, angle, firstHeading, secondHeading] = blueprint;
  const example = tool.industries[index % tool.industries.length];
  return [
    [firstHeading, [
      `${tool.definition} This guide focuses on ${angle}. Start with ${tool.inputs}. A polished result cannot repair incomplete source information, so collect the facts before opening the tool.`,
      `For ${industryNames}, the surrounding workflow differs, but the basic control is the same: use a consistent period or scope, identify who owns each input and record where the number or detail came from. That makes the result easier to review later.`
    ]],
    [secondHeading, [
      `The tool produces ${tool.outputs}. Read each output according to its definition instead of treating the most prominent number as the only answer. Compare it with the original business question and check whether assumptions changed while you worked.`,
      `${tool.caution} Save or export the result only after checking names, dates, rates, units and links. If the output affects payroll, tax, contracts or another regulated decision, confirm the applicable requirements independently.`
    ]],
    [`Worked ${example.name} scenario`, [
      `${example.scenario} The example is useful because it turns a broad question into concrete fields rather than presenting a fictional success claim. Enter the values in the same units and period, then compare the output with the underlying record.`,
      `For this scenario, the key details are ${example.rows.map(([key, value]) => `${key.toLowerCase()}: ${value}`).join('; ')}. ${example.why} The numbers are illustrations, not benchmarks; replace them with current business data.`
    ]],
    ['A repeatable step-by-step process', [
      tool.steps.map((step, stepIndex) => `${stepIndex + 1}. ${step}`).join(' '),
      `After completing the steps, have another person review the result when practical. A quick independent check often catches a transposed rate, an omitted cost, an outdated destination or a scope assumption that the original operator took for granted.`
    ]],
    ['Connect the result to the rest of your workflow', [
      `${example.records} Link the completed result to the relevant customer, job, campaign or reporting period so it can be found without relying on browser history. Use consistent filenames and avoid placing confidential information in fields that do not need it.`,
      `Continue with ${tool.related.map(path => `the Searya ${profiles[path].name}`).join(' and ')} when the next task requires it. The tools are designed to reduce repetitive arithmetic and formatting; responsibility for accurate inputs, legal requirements and final business decisions remains with the user.`
    ]]
  ];
}

export const TOOL_SEO_PROFILES = Object.freeze(profiles);

export const INDUSTRY_TOOL_PAGES = Object.freeze(Object.fromEntries(Object.entries(profiles).flatMap(([toolPath, tool]) => tool.industries.map(item => {
  const path = `${toolPath}/${item.slug}`;
  return [path, Object.freeze({
    ...item, path, toolPath, tool,
    title: `Free ${tool.name} for ${item.name.replace(/\b\w/g, char => char.toUpperCase())} | Searya`,
    description: `Use this free ${tool.name.toLowerCase()} for ${item.name}. Follow a tailored example, practical steps and industry-specific recordkeeping tips.`,
    h1: `Free ${tool.name} for ${item.name.replace(/\b\w/g, char => char.toUpperCase())}`
  })];
}))));

export const TOOL_GUIDES = Object.freeze(Object.fromEntries(Object.entries(profiles).flatMap(([toolPath, tool]) => guideBlueprints.map((blueprint, index) => {
  const [suffix, label, angle] = blueprint;
  const path = `/guides/${tool.slug}/${suffix}`;
  const h1 = `${tool.name}: ${label}`;
  return [path, Object.freeze({
    path, toolPath, toolSlug: tool.slug, toolName: tool.name, category: tool.name,
    title: `${h1} | Searya Guides`, h1,
    description: `Learn ${angle} with the free Searya ${tool.name.toLowerCase()}, realistic examples and a clear review process.`,
    intro: `Use the Searya ${tool.name} with more confidence. This guide explains ${angle}, shows how the result fits a real workflow and links every recommendation back to the working tool.`,
    publishedDate: '2026-08-19', readTime: '8 min read',
    sections: guideSections(tool, blueprint, index), relatedTools: tool.related,
    relatedGuides: guideBlueprints.filter((_, itemIndex) => itemIndex !== index).slice(0, 3).map(([otherSuffix]) => `/guides/${tool.slug}/${otherSuffix}`)
  })];
}))));

export const TOOL_GUIDE_PATHS = Object.freeze(Object.keys(TOOL_GUIDES));
